import time
import RPi.I2C as I2C
import Adafruit_I2C
import rplcd
import paho.mqtt.client as mqtt

# PCF8574 I2C address
I2C_ADDR = 0x27

# LCD configuration
LCD_RS = 1
LCD_E  = 2
LCD_D4 = 5
LCD_D5 = 6
LCD_D6 = 13
LCD_D7 = 19

# MQTT broker configuration
MQTT_BROKER = "your_mqtt_broker"
MQTT_TOPIC = "pcf8574_readings"

def setup_i2c():
    try:
        bus = I2C.I2C(1)
        bus.write_byte_data(I2C_ADDR, 0x0F, 0x06)  # Set the PCF8574 to 8-bit mode
        return Adafruit_I2C.I2C(I2C_ADDR, bus)
    except OSError as e:
        print(f"Error initializing I2C: {e}")
        return None

def setup_lcd():
    try:
        lcd = rplcd.CharLCD(rows=2, cols=16, pins_rs=LCD_RS, pins_e=LCD_E, pins_data=[LCD_D4, LCD_D5, LCD_D6, LCD_D7])
        lcd.clear()
        return lcd
    except rplcd.i2c.I2CUnavailable:
        print("Error initializing LCD")
        return None

def read_pcf8574(i2c):
    try:
        data = i2c.readfrom_i2c(I2C_ADDR, 8)
        return data.tobytes()
    except IOError as e:
        print(f"Error reading from PCF8574: {e}")
        return None

def publish_to_mqtt(client, data):
    try:
        client.publish(MQTT_TOPIC, "".join(map(str, data)))
    except Exception as e:
        print(f"Error publishing to MQTT broker: {e}")

def main():
    i2c = setup_i2c()
    if not i2c:
        exit(1)

    lcd = setup_lcd()
    if not lcd:
        exit(1)

    mqtt_client = mqtt.Client()
    mqtt_client.connect(MQTT_BROKER)

    while True:
        data = read_pcf8574(i2c)
        if data:
            lcd.message(data.decode())
            publish_to_mqtt(mqtt_client, data)

        time.sleep(1)

    mqtt_client.disconnect()
    i2c.close()
    lcd.clear()
    lcd.close()

if __name__ == "__main__":
    main()

