# NeoPixel setup
LED_PIN = 18
NUM_LEDS = 30  # Change this to the number of LEDs on your strip
LED_FREQ_HZ = 800000  # LED signal frequency in hertz (usually 800khz)
LED_DMA = 10  # DMA channel to use for generating signal (try 10)
LED_BRIGHTNESS = 64  # Set to 0 for off

# Create NeoPixel object
pixel_strip = neopixel.NeoPixel(LED_PIN, NUM_LEDS, brightness=LED_BRIGHTNESS, pixel_order=neopixel.GRB, auto_write=False)

def on_interrupt(signal, frame):
    print("Interrupted, exiting...")
    pixel_strip.deinit()
    sys.exit(0)

signal.signal(signal.SIGINT, on_interrupt)

def wheel(pos):
    if pos < 0 or pos > 255:
        raise ValueError("pos out of range")
    if pos < 85:
        return (255 - pos * 3, pos * 3, 0)
    if pos < 170:
        pos -= 85
        return (0, 255 - pos * 3, pos * 3)
    pos -= 170
    return (pos * 3, 0, 255 - pos * 3)

def animate():
    while True:
        for pos in range(NUM_LEDS):
            pixel_strip[pos] = wheel(pos)
            pixel_strip.show()
            time.sleep(0.5 / NUM_LEDS)

        time.sleep(0.5)

try:
    animate()
except KeyboardInterrupt:
    print("Interrupted, exiting...")
    pixel_strip.deinit()

