import adafruit_mqtt.client as mqtt
import re

# Set up MQTT client
mqtt_client = mqtt.MQTT_Client(client_id="serial_device_reader", server="mqtt_broker_ip", port=1883)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker!")
        client.publish("serial_device/status", "Connected")
    else:
        print(f"Failed to connect, return code {rc}")

def on_message(client, userdata, message):
    print(f"Received message: {str(message.payload.decode())}")

def read_serial_port():
    try:
        ser = serial.Serial("/dev/serial0", 9600, timeout=1)  # Adjust device and baud rate as needed
        valid_re = re.compile(r"^[-+]?\d+(\.\d+)?$")

        while True:
            line = ser.readline().decode().strip()
            if line:
                value = line.replace(",", ".")  # Ensure decimal separator is a dot
                if valid_re.match(value):
                    print(f"Received value: {value}")
                    mqtt_client.publish("serial_device/data", value)
                else:
                    print(f"Invalid value: {value}")
            time.sleep(5)

    except (pyserial.SerialException, KeyboardInterrupt):
        print("Error reading serial port or user interrupt, exiting...")
    finally:
        if ser and ser.isOpen():
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message

    try:
        mqtt_client.connect()
        mqtt_client.loop_forever()
        read_serial_port()
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        mqtt_client.disconnect()

