BAUD_RATE = 9600

def check_serial_port():
    ports = serial.tools.list_ports.comports()
    for port, desc, hwid in sorted(ports):
        if port.endswith(SERIAL_PORT):
            return port
    raise ValueError(f"Serial port {SERIAL_PORT} not found.")

def read_serial():
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=0.01)
        time.sleep(0.01)  # Give the device some time to initialize

        while True:
            line = ser.readline().decode().strip()
            if not line:
                continue

            try:
                value = float(line)
                if 0 < value < 100:
                    print(f"Received data: {value}")
                    mqtt_client.publish(MQTT_TOPIC, value)
                else:
                    print(f"Invalid data: {line}")
            except (ValueError, TypeError):
                print(f"Error processing data: {line}")

    except (FileNotFoundError, serial.SerialException) as e:
        print(f"Error reading from serial port: {e}")
    finally:
        if ser and ser.isOpen():
            ser.close()

