import BME280
import sys
from paho.mqtt import client as mqtt_client

I2C_ADDR = 0x76

def check_bme280():
    bus = smbus.SMBus(1)
    try:
        bus.write_byte_data(I2C_ADDR, BME280.BME280_REG_ID, BME280.BME280_ID_BME280)
        id = bus.read_byte_data(I2C_ADDR, BME280.BME280_REG_ID)
        if id != BME280.BME280_ID_BME280:
            return False
    except Exception as e:
        print(f"Error checking BME280: {e}")
        return False
    return True

def read_bme280(bus):
    sensor = BME280.BME280(i2c_dev=I2C_ADDR)
    try:
        sensor.begin()
        sensor.set_sensor_mode(BME280.BME280_OSAMP_8)
        data = sensor.read_all_registers()

        if not BME280.check_data_integrity(data):
            return None

        temperature = BME280.temperature_from_data(data)
        pressure = BME280.pressure_from_data(data)
        humidity = BME280.humidity_from_data(data)

        return temperature, pressure, humidity
    except Exception as e:
        print(f"Error reading BME280: {e}")
        return None

