import smbus2
import TSL2561
import sys
from paho.mqtt import client as mqtt_client

i2c = smbus2.SMBus(1)  # Use I2C bus 1 (GPIO pins SDA and SCL)

def check_device(address):
    try:
        i2c.write_byte_data(address, TSL2561.CMD_ID, TSL2561.CMD_ID)
        return True
    except Exception as e:
        print(f"Error checking TSL2561 device at address 0x{address}: {e}")
        return False

def read_and_validate_luminosity(address):
    try:
        data = i2c.read_i2c_block_data(address, TSL2561.CMD_VIS_IntegrationTime, 4)
        vis = (data[1] << 8) | data[2]
        data = i2c.read_i2c_block_data(address, TSL2561.CMD_IR_IntegrationTime, 4)
        ir = (data[1] << 8) | data[2]

        if vis < TSL2561.MIN_VIS or vis > TSL2561.MAX_VIS or ir < TSL2561.MIN_IR or ir > TSL2561.MAX_IR:
            raise ValueError("Invalid luminosity reading")

        return vis, ir
    except Exception as e:
        print(f"Error reading luminosity from TSL2561 device at address 0x{address}: {e}")
        return None, None

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
        client.subscribe("luminosity")
    else:
        print(f"Failed to connect, return code {rc}")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.topic}: {msg.payload.decode()}")

def main():
    if not check_device(0x39):
        print("TSL2561 device not found at address 0x39")
        sys.exit(1)

    mqtt_client.create_default_options()
    mqtt_client = mqtt_client.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message

    mqtt_client.connect("mqtt.example.com", 1883, 60)

    while True:
        try:
            vis, ir = read_and_validate_luminosity(0x39)
            if vis is not None and ir is not None:
                luminosity = (vis + ir) / 2
                mqtt_client.publish("luminosity", str(luminosity))
                print(f"Luminosity: {luminosity}")
        except Exception as e:
            print(f"Error reading luminosity: {e}")

        time.sleep(1)

    mqtt_client.disconnect()
    i2c.close()

if __name__ == "__main__":
    main()

