import RPi.GPIO as GPIO
import adafruit_pwm
import adafruit_pwm.servo
import paho.mqtt.client as mqtt
from adafruit_pwm.server import PWMOut

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

def check_pwm_pin(pin):
    try:
        pwm = PWMOut(pin, frequency=50)
        pwm.duty_cycle = 0
        pwm.deinit()
        return pin
    except OSError as e:
        print(f"Error initializing PWM on pin {pin}: {e}")
        return None

def main():
    gpio = GPIO.get_as_w1tc()
    for pin in PWM_PINS:
        gpio.setmode(GPIO.BCM)
        gpio.setup(pin, GPIO.OUT)
        pwm_pin = check_pwm_pin(pin)
        if pwm_pin is None:
            continue
        PWM_PINS[PWM_PINS.index(pin)] = pwm_pin

    try:
        while True:
            for pin, pwm in zip(PWM_PINS, PWM_PINS):
                duty_cycle = int(time.time() * 100) % 100
                if duty_cycle < 0 or duty_cycle > 100:
                    duty_cycle = 0
                gpio.output(pin, GPIO.HIGH)
                pwm.duty_cycle = duty_cycle
                print(f"Setting PWM on pin {pin} to {duty_cycle}%")

            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")

    for pin in PWM_PINS:
        if isinstance(pin, gpiozero.OutputDevice):
            pin.off()
        elif isinstance(pin, PWMOut):
